-- Unregistered owner-confirmed manual sharing and external acceptance over47.
-- No portal, auto-send, e-sign, invoice, journal, confirmed job or activation.
DO $review$ BEGIN
 IF (SELECT count(*) FROM pg_roles WHERE rolname IN('crest_quote_owner','crest_quote_integrity_owner','crest_lead_owner','crest_lead_integrity_owner','crest_schema_owner') AND NOT(rolcanlogin OR rolinherit OR rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls) AND rolconfig IS NULL)<>5 OR EXISTS(SELECT 1 FROM pg_auth_members m JOIN pg_roles r ON r.oid=m.roleid OR r.oid=m.member WHERE r.rolname IN('crest_quote_owner','crest_quote_integrity_owner','crest_lead_owner','crest_lead_integrity_owner','crest_schema_owner')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='CREST_QUOTE_ACCEPTANCE_SOURCE_REVIEW_REQUIRED';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('crest_private.quote_family_projection(crest.quote_families)') AND lower(array_to_string(proconfig,','))='search_path=pg_catalog, pg_temp' AND proowner='crest_schema_owner'::regrole AND prosecdef=false AND provolatile='i' AND NOT proleakproof AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='e52360a7f1d1f2db24ddd11122876563d436cf1ad722d038aa9be0eeb0bc7e01' AND lower(array_to_string(proconfig,',')) IN('search_path=pg_catalog, pg_temp','search_path=pg_catalog, pg_temp,row_security=on')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='CREST_QUOTE_ACCEPTANCE_SOURCE_REVIEW_REQUIRED';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('crest_private.quote_revision_projection(crest.quote_revisions)') AND lower(array_to_string(proconfig,','))='search_path=pg_catalog, pg_temp' AND proowner='crest_schema_owner'::regrole AND prosecdef=false AND provolatile='i' AND NOT proleakproof AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='403998e14bcb7f79eaf6e4869bf0787711ce84855a89af58f465036866166895' AND lower(array_to_string(proconfig,',')) IN('search_path=pg_catalog, pg_temp','search_path=pg_catalog, pg_temp,row_security=on')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='CREST_QUOTE_ACCEPTANCE_SOURCE_REVIEW_REQUIRED';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('crest_private.validate_quote_revision_change()') AND lower(array_to_string(proconfig,','))='search_path=pg_catalog, pg_temp' AND proowner='crest_schema_owner'::regrole AND prosecdef=false AND provolatile='v' AND NOT proleakproof AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='8b23066bb391628dd766d74946b048ce004c0099d41aa1fe254d6112ffde2a85' AND lower(array_to_string(proconfig,',')) IN('search_path=pg_catalog, pg_temp','search_path=pg_catalog, pg_temp,row_security=on')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='CREST_QUOTE_ACCEPTANCE_SOURCE_REVIEW_REQUIRED';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('crest_private.check_quote_audit()') AND lower(array_to_string(proconfig,','))='search_path=pg_catalog, pg_temp,row_security=on' AND proowner='crest_quote_integrity_owner'::regrole AND prosecdef=true AND provolatile='v' AND NOT proleakproof AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='54e0e82a9c332c3d178986c0932b433c0f6c535fa1eee45c9c55cbf75876aef1' AND lower(array_to_string(proconfig,',')) IN('search_path=pg_catalog, pg_temp','search_path=pg_catalog, pg_temp,row_security=on')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='CREST_QUOTE_ACCEPTANCE_SOURCE_REVIEW_REQUIRED';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('crest_private.check_lead_state_event()') AND lower(array_to_string(proconfig,','))='search_path=pg_catalog, pg_temp,row_security=on' AND proowner='crest_lead_integrity_owner'::regrole AND prosecdef=true AND provolatile='v' AND NOT proleakproof AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='bb0996e537224d914489a0fe59777e4e8702b0f24d42fcc315230973966bca1f' AND lower(array_to_string(proconfig,',')) IN('search_path=pg_catalog, pg_temp','search_path=pg_catalog, pg_temp,row_security=on')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='CREST_QUOTE_ACCEPTANCE_SOURCE_REVIEW_REQUIRED';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('crest_private.prepare_lead_event()') AND lower(array_to_string(proconfig,','))='search_path=pg_catalog, pg_temp' AND proowner='crest_schema_owner'::regrole AND prosecdef=false AND provolatile='v' AND NOT proleakproof AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='cad8c34fe478798693814499492f374eea925c24887c2ced806d7a4e68e76e9b' AND lower(array_to_string(proconfig,',')) IN('search_path=pg_catalog, pg_temp','search_path=pg_catalog, pg_temp,row_security=on')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='CREST_QUOTE_ACCEPTANCE_SOURCE_REVIEW_REQUIRED';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('crest_private.original_operation_reference_valid(jsonb)') AND lower(array_to_string(proconfig,','))='search_path=pg_catalog, pg_temp' AND proowner='crest_schema_owner'::regrole AND prosecdef=false AND provolatile='i' AND NOT proleakproof AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='b0908e26f4822559b8b0c937596ee0e77479187c17b06552a4f6bc698d88eaf1' AND lower(array_to_string(proconfig,',')) IN('search_path=pg_catalog, pg_temp','search_path=pg_catalog, pg_temp,row_security=on')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='CREST_QUOTE_ACCEPTANCE_SOURCE_REVIEW_REQUIRED';END IF;
 IF (SELECT count(*) FROM pg_class WHERE oid IN('crest.quote_families'::regclass,'crest.quote_revisions'::regclass,'crest.quote_items'::regclass,'crest.quote_approvals'::regclass,'crest.leads'::regclass,'crest.lead_events'::regclass,'crest.lead_conversions'::regclass) AND relowner='crest_schema_owner'::regrole AND relrowsecurity AND relforcerowsecurity)<>7 OR EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid IN('crest.quote_families'::regclass,'crest.quote_revisions'::regclass,'crest.quote_items'::regclass,'crest.leads'::regclass,'crest.lead_events'::regclass) AND NOT tgisinternal AND tgenabled<>'O') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='CREST_QUOTE_ACCEPTANCE_SOURCE_REVIEW_REQUIRED';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('crest_private.quote_operation_result(uuid,uuid,uuid)') AND lower(array_to_string(proconfig,','))='search_path=pg_catalog, pg_temp,row_security=on' AND proowner='crest_quote_owner'::regrole AND prosecdef=true AND provolatile='v' AND NOT proleakproof AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='6d897162ab21d25f239a97a003bdf54c0aec2b4afdfa52ce88ed0f15146890dd') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='CREST_QUOTE_ACCEPTANCE_SOURCE_REVIEW_REQUIRED';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('crest_private.check_quote_review_history()') AND lower(array_to_string(proconfig,','))='search_path=pg_catalog, pg_temp,row_security=on' AND proowner='crest_quote_integrity_owner'::regrole AND prosecdef=true AND provolatile='v' AND NOT proleakproof AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='4bd52ceeda014abe5ad1fc313bcf4774bc4c8cf15b7ce041167d9543e80f28e8') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='CREST_QUOTE_ACCEPTANCE_SOURCE_REVIEW_REQUIRED';END IF;
END $review$;
SET LOCAL ROLE crest_schema_owner;
CREATE TABLE crest.quote_family_commercial_state(id uuid PRIMARY KEY,business_id uuid NOT NULL,family_id uuid NOT NULL,active_offer_id uuid,initial_acceptance_id uuid,current_agreement_id uuid,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),created_by uuid NOT NULL,updated_by uuid NOT NULL,origin text NOT NULL CHECK(origin='manual'),operation_id uuid NOT NULL,import_row_id uuid CHECK(import_row_id IS NULL),UNIQUE(business_id,id),FOREIGN KEY(business_id,created_by) REFERENCES crest.memberships(business_id,actor_id),FOREIGN KEY(business_id,updated_by) REFERENCES crest.memberships(business_id,actor_id),FOREIGN KEY(business_id,operation_id,updated_by) REFERENCES crest_private.operations(business_id,operation_id,actor_id),UNIQUE(business_id,family_id),CHECK(id=family_id),FOREIGN KEY(business_id,family_id) REFERENCES crest.quote_families(business_id,id),FOREIGN KEY(business_id,family_id,active_offer_id) REFERENCES crest.quote_revisions(business_id,family_id,id));
ALTER TABLE crest.quote_family_commercial_state ENABLE ROW LEVEL SECURITY;ALTER TABLE crest.quote_family_commercial_state FORCE ROW LEVEL SECURITY;
CREATE TABLE crest.quote_sends(id uuid PRIMARY KEY,business_id uuid NOT NULL,family_id uuid NOT NULL,revision_id uuid NOT NULL,approval_id uuid NOT NULL,channel text NOT NULL CHECK(channel IN('text','phone','email','in_person')),recipient_snapshot jsonb NOT NULL,confirmed_at timestamptz NOT NULL DEFAULT clock_timestamp(),evidence_note text CHECK(crest_private.quote_review_note_valid(to_jsonb(evidence_note))),presentation_hash text NOT NULL,replaces_revision_id uuid,request jsonb NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),created_by uuid NOT NULL,updated_by uuid NOT NULL,origin text NOT NULL CHECK(origin='manual'),operation_id uuid NOT NULL,import_row_id uuid CHECK(import_row_id IS NULL),UNIQUE(business_id,id),FOREIGN KEY(business_id,created_by) REFERENCES crest.memberships(business_id,actor_id),FOREIGN KEY(business_id,updated_by) REFERENCES crest.memberships(business_id,actor_id),FOREIGN KEY(business_id,operation_id,updated_by) REFERENCES crest_private.operations(business_id,operation_id,actor_id),CHECK(version=1 AND created_at=updated_at AND created_by=updated_by),UNIQUE(business_id,id,family_id,revision_id),UNIQUE(business_id,operation_id),FOREIGN KEY(business_id,family_id,revision_id) REFERENCES crest.quote_revisions(business_id,family_id,id),FOREIGN KEY(business_id,approval_id) REFERENCES crest.quote_approvals(business_id,id),FOREIGN KEY(business_id,family_id,replaces_revision_id) REFERENCES crest.quote_revisions(business_id,family_id,id),CHECK(confirmed_at=created_at));
ALTER TABLE crest.quote_sends ENABLE ROW LEVEL SECURITY;ALTER TABLE crest.quote_sends FORCE ROW LEVEL SECURITY;
CREATE TABLE crest.quote_acceptances(id uuid PRIMARY KEY,business_id uuid NOT NULL,family_id uuid NOT NULL,revision_id uuid NOT NULL,send_id uuid NOT NULL,customer_id uuid NOT NULL,lead_id uuid,conversion_id uuid,counterparty_snapshot jsonb NOT NULL,content_hash text NOT NULL,channel text NOT NULL CHECK(channel IN('text','phone','email','in_person')),confirmation_effective_at timestamptz NOT NULL CHECK(isfinite(confirmation_effective_at)),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),evidence_note text NOT NULL CHECK(crest_private.quote_review_note_valid(to_jsonb(evidence_note))),request jsonb NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),created_by uuid NOT NULL,updated_by uuid NOT NULL,origin text NOT NULL CHECK(origin='manual'),operation_id uuid NOT NULL,import_row_id uuid CHECK(import_row_id IS NULL),UNIQUE(business_id,id),FOREIGN KEY(business_id,created_by) REFERENCES crest.memberships(business_id,actor_id),FOREIGN KEY(business_id,updated_by) REFERENCES crest.memberships(business_id,actor_id),FOREIGN KEY(business_id,operation_id,updated_by) REFERENCES crest_private.operations(business_id,operation_id,actor_id),CHECK(version=1 AND created_at=updated_at AND created_by=updated_by),UNIQUE(business_id,family_id),UNIQUE(business_id,revision_id),UNIQUE(business_id,id,family_id,customer_id),UNIQUE(business_id,operation_id),FOREIGN KEY(business_id,send_id,family_id,revision_id) REFERENCES crest.quote_sends(business_id,id,family_id,revision_id),FOREIGN KEY(business_id,customer_id) REFERENCES crest.customers(business_id,id),FOREIGN KEY(business_id,lead_id) REFERENCES crest.leads(business_id,id),CHECK(recorded_at=created_at AND confirmation_effective_at<=recorded_at));
ALTER TABLE crest.quote_acceptances ENABLE ROW LEVEL SECURITY;ALTER TABLE crest.quote_acceptances FORCE ROW LEVEL SECURITY;
CREATE TABLE crest.agreements(id uuid PRIMARY KEY,business_id uuid NOT NULL,family_id uuid NOT NULL,acceptance_id uuid NOT NULL,customer_id uuid NOT NULL,version_no bigint NOT NULL CHECK(version_no=1),parent_agreement_id uuid CHECK(parent_agreement_id IS NULL),total_cents bigint NOT NULL CHECK(total_cents>=0),signed_delta_cents bigint NOT NULL CHECK(signed_delta_cents=total_cents),customer_snapshot jsonb NOT NULL,effective_at timestamptz NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),created_by uuid NOT NULL,updated_by uuid NOT NULL,origin text NOT NULL CHECK(origin='manual'),operation_id uuid NOT NULL,import_row_id uuid CHECK(import_row_id IS NULL),UNIQUE(business_id,id),FOREIGN KEY(business_id,created_by) REFERENCES crest.memberships(business_id,actor_id),FOREIGN KEY(business_id,updated_by) REFERENCES crest.memberships(business_id,actor_id),FOREIGN KEY(business_id,operation_id,updated_by) REFERENCES crest_private.operations(business_id,operation_id,actor_id),CHECK(version=1 AND created_at=updated_at AND created_by=updated_by),UNIQUE(business_id,family_id,version_no),UNIQUE(business_id,acceptance_id),UNIQUE(business_id,id,family_id),FOREIGN KEY(business_id,acceptance_id,family_id,customer_id) REFERENCES crest.quote_acceptances(business_id,id,family_id,customer_id));
ALTER TABLE crest.agreements ENABLE ROW LEVEL SECURITY;ALTER TABLE crest.agreements FORCE ROW LEVEL SECURITY;
CREATE TABLE crest.scope_entitlements(id uuid PRIMARY KEY,business_id uuid NOT NULL,agreement_family_id uuid NOT NULL,stable_line_key uuid NOT NULL,initial_quote_item_id uuid NOT NULL,vehicle_id uuid,job_wide boolean NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),created_by uuid NOT NULL,updated_by uuid NOT NULL,origin text NOT NULL CHECK(origin='manual'),operation_id uuid NOT NULL,import_row_id uuid CHECK(import_row_id IS NULL),UNIQUE(business_id,id),FOREIGN KEY(business_id,created_by) REFERENCES crest.memberships(business_id,actor_id),FOREIGN KEY(business_id,updated_by) REFERENCES crest.memberships(business_id,actor_id),FOREIGN KEY(business_id,operation_id,updated_by) REFERENCES crest_private.operations(business_id,operation_id,actor_id),CHECK(version=1 AND created_at=updated_at AND created_by=updated_by),UNIQUE(business_id,agreement_family_id,stable_line_key),UNIQUE(business_id,id,agreement_family_id),FOREIGN KEY(business_id,agreement_family_id) REFERENCES crest.quote_families(business_id,id),FOREIGN KEY(business_id,initial_quote_item_id) REFERENCES crest.quote_items(business_id,id),FOREIGN KEY(business_id,vehicle_id) REFERENCES crest.vehicles(business_id,id),CHECK(vehicle_id IS NOT NULL AND NOT job_wide OR vehicle_id IS NULL AND job_wide));
ALTER TABLE crest.scope_entitlements ENABLE ROW LEVEL SECURITY;ALTER TABLE crest.scope_entitlements FORCE ROW LEVEL SECURITY;
CREATE TABLE crest.entitlement_versions(id uuid PRIMARY KEY,business_id uuid NOT NULL,family_id uuid NOT NULL,entitlement_id uuid NOT NULL,agreement_id uuid NOT NULL,authorized_cents bigint NOT NULL CHECK(authorized_cents>=0),scope_snapshot jsonb NOT NULL,source_quote_item_id uuid NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),created_by uuid NOT NULL,updated_by uuid NOT NULL,origin text NOT NULL CHECK(origin='manual'),operation_id uuid NOT NULL,import_row_id uuid CHECK(import_row_id IS NULL),UNIQUE(business_id,id),FOREIGN KEY(business_id,created_by) REFERENCES crest.memberships(business_id,actor_id),FOREIGN KEY(business_id,updated_by) REFERENCES crest.memberships(business_id,actor_id),FOREIGN KEY(business_id,operation_id,updated_by) REFERENCES crest_private.operations(business_id,operation_id,actor_id),CHECK(version=1 AND created_at=updated_at AND created_by=updated_by),UNIQUE(business_id,entitlement_id,agreement_id),UNIQUE(business_id,id,entitlement_id,agreement_id),FOREIGN KEY(business_id,entitlement_id,family_id) REFERENCES crest.scope_entitlements(business_id,id,agreement_family_id),FOREIGN KEY(business_id,agreement_id,family_id) REFERENCES crest.agreements(business_id,id,family_id),FOREIGN KEY(business_id,source_quote_item_id) REFERENCES crest.quote_items(business_id,id));
ALTER TABLE crest.entitlement_versions ENABLE ROW LEVEL SECURITY;ALTER TABLE crest.entitlement_versions FORCE ROW LEVEL SECURITY;
CREATE TABLE crest.scope_allocations(id uuid PRIMARY KEY,business_id uuid NOT NULL,entitlement_id uuid NOT NULL,agreement_id uuid NOT NULL,entitlement_version_id uuid NOT NULL,job_id uuid CHECK(job_id IS NULL),amount_cents bigint NOT NULL CHECK(amount_cents>=0),gross_inclusive_cents bigint NOT NULL CHECK(gross_inclusive_cents>=0),discount_inclusive_cents bigint NOT NULL CHECK(discount_inclusive_cents>=0),stable_partition_id uuid NOT NULL,scope_description text NOT NULL,scope_snapshot jsonb NOT NULL,allocation_state text NOT NULL CHECK(allocation_state='unassigned'),replaces_id uuid CHECK(replaces_id IS NULL),version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),created_by uuid NOT NULL,updated_by uuid NOT NULL,origin text NOT NULL CHECK(origin='manual'),operation_id uuid NOT NULL,import_row_id uuid CHECK(import_row_id IS NULL),UNIQUE(business_id,id),FOREIGN KEY(business_id,created_by) REFERENCES crest.memberships(business_id,actor_id),FOREIGN KEY(business_id,updated_by) REFERENCES crest.memberships(business_id,actor_id),FOREIGN KEY(business_id,operation_id,updated_by) REFERENCES crest_private.operations(business_id,operation_id,actor_id),CHECK(version=1 AND created_at=updated_at AND created_by=updated_by),UNIQUE(business_id,stable_partition_id),UNIQUE(business_id,entitlement_version_id),FOREIGN KEY(business_id,entitlement_version_id,entitlement_id,agreement_id) REFERENCES crest.entitlement_versions(business_id,id,entitlement_id,agreement_id),CHECK(amount_cents::numeric=gross_inclusive_cents::numeric-discount_inclusive_cents::numeric));
ALTER TABLE crest.scope_allocations ENABLE ROW LEVEL SECURITY;ALTER TABLE crest.scope_allocations FORCE ROW LEVEL SECURITY;
ALTER TABLE crest.lead_conversions ADD CONSTRAINT conversion_commercial_binding UNIQUE(business_id,id,lead_id,customer_id);
ALTER TABLE crest.quote_acceptances ADD CONSTRAINT acceptance_conversion_binding FOREIGN KEY(business_id,conversion_id,lead_id,customer_id) REFERENCES crest.lead_conversions(business_id,id,lead_id,customer_id);
ALTER TABLE crest.quote_acceptances ADD CONSTRAINT acceptance_family_key UNIQUE(business_id,id,family_id);
ALTER TABLE crest.quote_family_commercial_state ADD CONSTRAINT commercial_acceptance_family FOREIGN KEY(business_id,initial_acceptance_id,family_id) REFERENCES crest.quote_acceptances(business_id,id,family_id) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE crest.quote_family_commercial_state ADD CONSTRAINT commercial_agreement_family FOREIGN KEY(business_id,current_agreement_id,family_id) REFERENCES crest.agreements(business_id,id,family_id) DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION crest_private.quote_family_commercial_state_projection(v crest.quote_family_commercial_state) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$ SELECT to_jsonb(v)||jsonb_build_object('version',(v).version::text,'created_at',to_char((v).created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'updated_at',to_char((v).updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) $$;
CREATE FUNCTION crest_private.quote_sends_projection(v crest.quote_sends) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$ SELECT to_jsonb(v)||jsonb_build_object('version',(v).version::text,'created_at',to_char((v).created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'updated_at',to_char((v).updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'confirmed_at',to_char((v).confirmed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) $$;
