CREATE FUNCTION crest_private.agreements_projection(v crest.agreements) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$ SELECT to_jsonb(v)||jsonb_build_object('version',(v).version::text,'version_no',(v).version_no::text,'total_cents',(v).total_cents::text,'signed_delta_cents',(v).signed_delta_cents::text,'created_at',to_char((v).created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'updated_at',to_char((v).updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'effective_at',to_char((v).effective_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) $$;
CREATE FUNCTION crest_private.scope_entitlements_projection(v crest.scope_entitlements) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$ SELECT to_jsonb(v)||jsonb_build_object('version',(v).version::text,'created_at',to_char((v).created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'updated_at',to_char((v).updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) $$;
CREATE FUNCTION crest_private.entitlement_versions_projection(v crest.entitlement_versions) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$ SELECT to_jsonb(v)||jsonb_build_object('version',(v).version::text,'authorized_cents',(v).authorized_cents::text,'created_at',to_char((v).created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'updated_at',to_char((v).updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) $$;
CREATE FUNCTION crest_private.scope_allocations_projection(v crest.scope_allocations) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$ SELECT to_jsonb(v)||jsonb_build_object('version',(v).version::text,'amount_cents',(v).amount_cents::text,'gross_inclusive_cents',(v).gross_inclusive_cents::text,'discount_inclusive_cents',(v).discount_inclusive_cents::text,'created_at',to_char((v).created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'updated_at',to_char((v).updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) $$;
CREATE FUNCTION crest_private.stamp_quote_commercial() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$ DECLARE stamp timestamptz:=clock_timestamp();BEGIN IF TG_OP='INSERT' THEN NEW.created_at:=stamp;IF NEW.version<>1 OR NEW.created_by<>NEW.updated_by THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='CREST_QUOTE_COMMERCIAL_HISTORY_REQUIRED';END IF;ELSE IF TG_TABLE_NAME<>'quote_family_commercial_state' OR ROW(NEW.id,NEW.business_id,NEW.family_id,NEW.created_at,NEW.created_by,NEW.origin,NEW.import_row_id) IS DISTINCT FROM ROW(OLD.id,OLD.business_id,OLD.family_id,OLD.created_at,OLD.created_by,OLD.origin,OLD.import_row_id) OR NEW.version<>OLD.version+1 OR OLD.initial_acceptance_id IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='CREST_QUOTE_COMMERCIAL_HISTORY_RETAINED';END IF;END IF;NEW.updated_at:=stamp;IF TG_TABLE_NAME='quote_sends' THEN NEW.confirmed_at:=stamp;ELSIF TG_TABLE_NAME='quote_acceptances' THEN NEW.recorded_at:=stamp;END IF;RETURN NEW;END $$;
CREATE FUNCTION crest_private.reject_quote_commercial_removal() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$ BEGIN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='CREST_QUOTE_COMMERCIAL_HISTORY_RETAINED';END $$;
