CREATE OR REPLACE FUNCTION crest_private.check_lead_state_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET row_security=on AS $check$
DECLARE outcome jsonb;event crest.lead_events;
BEGIN
 IF TG_TABLE_NAME='leads' THEN SELECT * INTO event FROM crest.lead_events WHERE business_id=NEW.business_id AND lead_id=NEW.id AND lead_version=NEW.version AND operation_id=NEW.operation_id AND (quote_send_id IS NOT NULL OR acceptance_id IS NOT NULL);ELSE event:=NEW::crest.lead_events;END IF;
 IF event.quote_send_id IS NOT NULL OR event.acceptance_id IS NOT NULL THEN PERFORM set_config('crest.business_id',NEW.business_id::text,true),set_config('crest.actor_id',NEW.updated_by::text,true);outcome:=crest_private.quote_commercial_operation_result(NEW.business_id,NEW.updated_by,NEW.operation_id);IF outcome->'receipt'->>'leadId' IS DISTINCT FROM event.lead_id::text OR outcome->'receipt'->>'leadVersion' IS DISTINCT FROM event.lead_version::text OR outcome->'receipt'->>'leadEventId' IS DISTINCT FROM event.id::text THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='CREST_QUOTE_LEAD_SOURCE_REQUIRED';END IF;RETURN NULL;END IF;
 IF TG_TABLE_NAME='leads' THEN
   IF NEW.state IS NOT DISTINCT FROM OLD.state AND NEW.lost_reason IS NOT DISTINCT FROM OLD.lost_reason THEN RETURN NULL;END IF;
   outcome:=crest_private.lead_state_operation_result(NEW.business_id,NEW.updated_by,NEW.operation_id);
   IF outcome->'receipt'->>'leadId' IS DISTINCT FROM NEW.id::text OR outcome->'receipt'->>'leadVersion' IS DISTINCT FROM NEW.version::text THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='CREST_LEAD_STATE_EVENT_REQUIRED';END IF;
 ELSE
   outcome:=crest_private.lead_state_operation_result(NEW.business_id,NEW.created_by,NEW.operation_id);
   IF outcome->'receipt'->>'leadEventId' IS DISTINCT FROM NEW.id::text THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='CREST_LEAD_STATE_EVENT_REQUIRED';END IF;
 END IF;RETURN NULL;
END
$check$;
RESET ROLE;
REVOKE CREATE ON SCHEMA crest_private FROM crest_lead_integrity_owner;
SET LOCAL ROLE crest_schema_owner;
CREATE OR REPLACE FUNCTION crest_private.original_operation_reference_valid(v jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
DECLARE kind text;r jsonb;keys text[];key text;
BEGIN
 IF v IS NULL OR jsonb_typeof(v)<>'object' OR NOT(v?&ARRAY['schemaVersion','businessId','commandType','reference']) OR v-ARRAY['schemaVersion','businessId','commandType','reference']<>'{}'::jsonb OR v->'schemaVersion' IS DISTINCT FROM '1'::jsonb OR NOT crest_private.original_operation_uuid(v->'businessId') OR jsonb_typeof(v->'commandType') IS DISTINCT FROM 'string' THEN RETURN false;END IF;
 kind:=v->>'commandType';r:=v->'reference';
 keys:=CASE kind
  WHEN 'business.rename' THEN ARRAY['expectedVersion']
  WHEN 'crm.customer.save' THEN ARRAY['customerId','expectedVersion']
  WHEN 'crm.address.save' THEN ARRAY['customerId','addressId','expectedVersion']
  WHEN 'crm.vehicle.save' THEN ARRAY['vehicleId','expectedVersion']
  WHEN 'crm.vehicle.association' THEN ARRAY['action','associationId','vehicleId','expectedVersion','nextAssociationId']
  WHEN 'crm.lead.source.save' THEN ARRAY['leadSourceId','expectedVersion']
  WHEN 'crm.lead.save' THEN ARRAY['leadId','expectedVersion']
  WHEN 'crm.lead.state' THEN ARRAY['leadId','expectedVersion']
  WHEN 'crm.lead.vehicle.save' THEN ARRAY['leadId','leadVehicleId','expectedVersion']
  WHEN 'crm.lead.address.save' THEN ARRAY['leadId','leadAddressId','expectedVersion']
  WHEN 'crm.lead.convert' THEN ARRAY['conversionId','leadId','expectedLeadVersion','customerId']
  WHEN 'catalog.service.save' THEN ARRAY['serviceId','expectedRevision']
  WHEN 'operations.appointment_hold.save' THEN ARRAY['holdId','expectedSequence']
  WHEN 'quote.draft.save' THEN ARRAY['familyId','revisionId','expectedFamilyVersion','expectedRevisionVersion']
  WHEN 'quote.review.submit' THEN ARRAY['familyId','revisionId','expectedFamilyVersion','expectedRevisionVersion','expectedContentVersion']
  WHEN 'quote.review.approve' THEN ARRAY['familyId','revisionId','expectedFamilyVersion','expectedRevisionVersion','expectedContentVersion','approvalId']
 WHEN 'quote.manual.send' THEN ARRAY['familyId','revisionId','expectedFamilyVersion','expectedRevisionVersion','expectedContentVersion','sendId','approvalId']
 WHEN 'quote.confirmation.accept' THEN ARRAY['familyId','revisionId','expectedFamilyVersion','expectedRevisionVersion','expectedContentVersion','acceptanceId','agreementId']
 WHEN 'quote.replacement.create' THEN ARRAY['familyId','revisionId','expectedFamilyVersion','expectedRevisionVersion'] ELSE NULL END;
 IF keys IS NULL OR jsonb_typeof(r) IS DISTINCT FROM 'object' THEN RETURN false;END IF;
 keys:=ARRAY['operationId','recoveryEpoch']||keys;
 IF NOT(r?&keys) OR r-keys<>'{}'::jsonb THEN RETURN false;END IF;
 FOREACH key IN ARRAY keys LOOP
  IF key IN ('expectedSequence','expectedVersion','expectedRevision','expectedFamilyVersion','expectedRevisionVersion','expectedContentVersion') THEN IF NOT crest_private.original_operation_version(r->key,kind NOT IN ('business.rename','crm.lead.state','quote.review.submit','quote.review.approve','quote.manual.send','quote.confirmation.accept')) THEN RETURN false;END IF;
  ELSIF key='expectedLeadVersion' THEN IF NOT crest_private.original_operation_version(r->key,false) THEN RETURN false;END IF;
  ELSIF key NOT IN ('action','nextAssociationId') THEN IF NOT crest_private.original_operation_uuid(r->key) THEN RETURN false;END IF;END IF;
 END LOOP;
 IF kind='crm.vehicle.association' THEN RETURN coalesce(jsonb_typeof(r->'action')='string' AND r->>'action' IN ('open','close','transfer') AND r->>'expectedVersion'=CASE WHEN r->>'action'='open' THEN '0' ELSE '1' END AND CASE WHEN r->>'action'='transfer' THEN crest_private.original_operation_uuid(r->'nextAssociationId') AND r->>'nextAssociationId'<>r->>'associationId' ELSE r->'nextAssociationId'='null'::jsonb END,false);END IF;
 IF kind='quote.replacement.create' AND (r->>'expectedFamilyVersion'='0' OR r->>'expectedRevisionVersion'<>'0') THEN RETURN false;END IF;
 IF kind='quote.draft.save' AND ((r->>'expectedFamilyVersion'='0')<>(r->>'expectedRevisionVersion'='0')) THEN RETURN false;END IF;
 RETURN true;
END $$;
RESET ROLE;
REVOKE ALL ON FUNCTION crest_private.quote_family_commercial_state_projection(crest.quote_family_commercial_state),crest_private.quote_sends_projection(crest.quote_sends),crest_private.quote_acceptances_projection(crest.quote_acceptances),crest_private.agreements_projection(crest.agreements),crest_private.scope_entitlements_projection(crest.scope_entitlements),crest_private.entitlement_versions_projection(crest.entitlement_versions),crest_private.scope_allocations_projection(crest.scope_allocations),crest_private.stamp_quote_commercial(),crest_private.reject_quote_commercial_removal(),crest_private.quote_counterparty_valid(jsonb),crest_private.quote_commercial_body_valid(text,jsonb),crest_private.quote_commercial_digest(uuid,uuid,uuid,text,uuid,uuid,bigint,bigint,bigint,text,uuid,uuid,jsonb),crest_private.insert_quote_commercial_audit(uuid,uuid,uuid,text,uuid,bigint,text,jsonb,jsonb),crest_private.apply_quote_derived_lead(uuid,uuid,uuid,uuid,uuid,uuid,timestamptz),crest_private.quote_commercial_audit_image(uuid,uuid,uuid,uuid,text,uuid,bigint,text),crest_private.quote_commercial_operation_result(uuid,uuid,uuid),crest_private.apply_quote_commercial(bytea,uuid,uuid,text,uuid,uuid,timestamptz,uuid,uuid,uuid,integer,uuid,uuid,bigint,bigint,bigint,text,uuid,uuid,jsonb,text),crest_private.check_quote_commercial_row(),crest_private.check_quote_commercial_final(),crest_commands.confirm_quote_manual_send(bytea,uuid,uuid,text,uuid,uuid,timestamptz,uuid,uuid,uuid,integer,uuid,uuid,bigint,bigint,bigint,text,uuid,uuid,jsonb),crest_commands.accept_quote_confirmation(bytea,uuid,uuid,text,uuid,uuid,timestamptz,uuid,uuid,uuid,integer,uuid,uuid,bigint,bigint,bigint,text,uuid,uuid,jsonb),crest_commands.lookup_quote_commercial_operation(bytea,uuid,uuid,text,uuid,uuid,timestamptz,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION crest_private.quote_family_commercial_state_projection(crest.quote_family_commercial_state),crest_private.quote_sends_projection(crest.quote_sends),crest_private.quote_acceptances_projection(crest.quote_acceptances),crest_private.agreements_projection(crest.agreements),crest_private.scope_entitlements_projection(crest.scope_entitlements),crest_private.entitlement_versions_projection(crest.entitlement_versions),crest_private.scope_allocations_projection(crest.scope_allocations),crest_private.quote_counterparty_valid(jsonb),crest_private.quote_commercial_body_valid(text,jsonb),crest_private.quote_commercial_digest(uuid,uuid,uuid,text,uuid,uuid,bigint,bigint,bigint,text,uuid,uuid,jsonb),crest_private.insert_quote_commercial_audit(uuid,uuid,uuid,text,uuid,bigint,text,jsonb,jsonb),crest_private.apply_quote_derived_lead(uuid,uuid,uuid,uuid,uuid,uuid,timestamptz),crest_private.quote_commercial_audit_image(uuid,uuid,uuid,uuid,text,uuid,bigint,text) TO crest_quote_owner,crest_quote_integrity_owner;
